"""Import the requested Tripo/ElevenLabs reward deliveries; never submit jobs."""
import array,hashlib,json,math,shutil,struct,subprocess,wave
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
JOB=ROOT/'artifacts/model-jobs/quest-rewards/2026-10-15'
AUDIO=ROOT/'artifacts/audio-production/quest-rewards/2026-10-15'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,j):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(j,indent=2)+'\n',encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    runtime=ROOT/'assets/runtime';models=runtime/'models/rewards'
    records=[];specs=[]
    for row in read(JOB/'normalization.json'):
        p=models/row['file'];b=p.read_bytes();n=struct.unpack_from('<I',b,12)[0];gltf=json.loads(b[20:20+n])
        primitive=gltf['meshes'][0]['primitives'][0];acc=gltf['accessors'][primitive['attributes']['POSITION']]
        lo,hi=acc['min'],acc['max'];count=sum(gltf['accessors'][p['indices']]['count']//3 for p in gltf['meshes'][0]['primitives'])
        assert count==row['triangles'] and max(hi[i]-lo[i] for i in range(3))<.6
        assert gltf.get('images'),'Export lost provider textures'
        row=dict(row,minimum=lo,maximum=hi,sha256=sha(p),bytes=p.stat().st_size,rightsRecord='assets/models/rewards/NOTICE.md')
        records.append(row)
        vec=lambda xs:'{'+','.join(f'{v:.9f}f' for v in xs)+'}'
        specs.append('{'+','.join([json.dumps(row['name']),json.dumps(row['id']),json.dumps(row['url']),vec(lo),vec(hi),str(count)])+'},')
        name=row['name'].removeprefix('reward_')
        shutil.copyfile(ROOT/f'artifacts/model-jobs/quest-reward-{name}/2026-10-15/model.glb.provenance.json',models/(row['name']+'.provenance.json'))
    write(models/'manifest.json',dict(schemaVersion=1,assets=records))
    (ROOT/'src/reward_manifest.inc').write_text('// Generated by scripts/prepare-quest-rewards.py. Y-up metres; centered pivots.\nstatic const paws::GardenAsset rewardInputs[] = {\n'+'\n'.join(specs)+'\n};\n')
    (models/'NOTICE.md').write_text('# Quest reward models\n\nCoin and heart generated with Tripo3D from original OpenAI ImageGen references on 15 October 2026. No third-party reference images were used. Provider originals, reference prompts and SHA-256 records, editable Blender sources, processing script and review images are retained under artifacts/model-jobs/quest-rewards and artifacts/model-input-images/quest-rewards. Runtime variants retain provider base-color and normal maps at 512 pixels; texture-island positions were welded before simplification. Pivots are centered, Y is up, and fronts face +Z. Tripo account entitlement and distribution terms remain unverified; no third-party asset license is invented.\n')
    rights=AUDIO/'rights-status.txt';rights.write_text('Generated through the configured ElevenLabs Sound Effects account for the requested Paws reward sequence on 15 October 2026. Originals and provider provenance are retained here. Account plan entitlement and required attribution remain unverified. No universal commercial license or human listening approval is asserted.\n')
    catalogPath=runtime/'audio/catalog.json';catalog=read(catalogPath)
    previous=AUDIO/'previous-coin-catalog.json'
    if not previous.exists():
        old=next(c for c in catalog['clips'] if c['id']=='reward_coins_01');write(previous,old)
        shutil.copyfile(runtime/'audio'/old['file'],AUDIO/'previous-reward-coins.wav')
    for name,clipId,family in [('coin-reward','reward_coins_01','reward_coins'),('friendship-purr','reward_friendship_01','reward_friendship')]:
        original=AUDIO/(name+'.mp3');provenance=read(original.with_suffix('.mp3.provenance.json'));assert sha(original)==provenance['sha256']
        pcm=array.array('f');pcm.frombytes(subprocess.check_output(['ffmpeg','-v','error','-i',str(original),'-f','f32le','-acodec','pcm_f32le','-ar','44100','-ac','1','pipe:1']))
        assert pcm and all(math.isfinite(x) for x in pcm)
        mean=sum(pcm)/len(pcm);samples=[x-mean for x in pcm];fade=min(1102,len(samples)//2)
        for i in range(fade):samples[i]*=i/fade;samples[-i-1]*=i/fade
        peak=max(abs(x) for x in samples);assert peak>.0001
        gain=10**(-6/20)/peak;integers=array.array('h',(round(x*gain*32767) for x in samples))
        dest=runtime/'audio'/(clipId+'.wav')
        with wave.open(str(dest),'wb') as w:w.setparams((1,2,44100,len(integers),'NONE','not compressed'));w.writeframes(integers.tobytes())
        duration=len(integers)/44100;peakDb=20*math.log10(max(abs(x) for x in integers)/32768);rms=math.sqrt(sum(x*x for x in integers)/len(integers))/32768
        record=dict(id=clipId,family=family,provider='ElevenLabs',prompt=provenance['request']['text'],target=f'{duration:.3f} s',event='Coin phase' if name=='coin-reward' else 'Friendship heart phase',file=dest.name,loop=False,accepted=False,playable=True,
          source=dict(provider='ElevenLabs',assetId='sha256:'+sha(original),url=provenance['endpoint'],generatedAt=provenance['generated_at'],prompt=provenance['request']['text'],settings=provenance['request'],original=original.relative_to(ROOT).as_posix(),originalSha256=sha(original),rightsRecord=rights.relative_to(ROOT).as_posix(),rightsSha256=sha(rights),processing=['Mono 44100 Hz PCM, DC removed, 25 ms entry/exit fades, peak -6 dBFS'],licenseNotice='Account rights remain unverified.'),
          review=dict(technicalVerified=True,approved=False,sourceAuditioned=False,journeyAuditioned=False,notes='Finite, non-silent PCM, peak/headroom, fades and source hash verified; no human listening claim.'),
          pcm=dict(sampleRate=44100,channels=1,frames=len(integers),duration=duration,peakDbfs=peakDb,rmsDbfs=20*math.log10(rms),dc=[sum(integers)/len(integers)/32768],pcmBytesAtDeviceRate=math.ceil(duration*48000)*4,seamStep=0),sha256=sha(dest),bytes=dest.stat().st_size,loopFrames=None)
        old=next((n for n,c in enumerate(catalog['clips']) if c['id']==clipId),None)
        if old is None:catalog['clips'].append(record)
        else:catalog['clips'][old]=record
        write(AUDIO/(clipId+'-delivery.json'),record)
    write(catalogPath,catalog)
    header=ROOT/'src/audio_catalog.hpp';text=header.read_text().replace('AudioClipSpec,66>','AudioClipSpec,67>')
    if '"reward_friendship_01"' not in text:text=text.replace('}};','    {"reward_friendship_01","reward_friendship",2,false,0.35f,0.12},\n}};')
    header.write_text(text)
    print(json.dumps(dict(models=records,audioClips=len(catalog['clips'])),indent=2))
if __name__=='__main__':main()
